fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // Determine the output length according to broadcasting rules
    let len = m.max(n);

    // Optional sanity check:
    // Ensure the inputs are compatible: either same length or one of them has length 1
    assert!(
        m == n || m == 1 || n == 1,
        "Input lengths are not compatible for broadcasting"
    );

    // Broadcast `a`: if its length is 1, repeat the single element; otherwise, keep it as is.
    let a_broadcasted = if m == 1 {
        // Safe to index at 0 because m == 1 implies a.len() >= 1
        vec![a[0]; len]
    } else {
        // When m == len, just use the original vector
        a
    };

    // Broadcast `b` in the same manner
    let b_broadcasted = if n == 1 {
        vec![b[0]; len]
    } else {
        b
    };

    (a_broadcasted, b_broadcasted)
}

